package com.cptvsan.adapter;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;

/**
 * Every key the Java tree builds is byte for byte the key the Python pack's
 * metric_tree.build_key builds. tests/fixtures/python-keys.tsv is GENERATED by
 * tools/gen_metric_tree.py from the Python code (ci runs it with --check, so a
 * stale fixture fails); each row is entity, identity parts, metric, Python key.
 * The Java side parses the ref, builds the key through StatKeys, and the two
 * key SETS are diffed in both directions.
 */
public final class KeyParityTest {

    public static void main(String[] args) throws Exception {
        List<String> lines = Files.readAllLines(Paths.get("tests", "fixtures", "python-keys.tsv"));
        Set<String> python = new TreeSet<>();
        Set<String> java = new TreeSet<>();
        Set<String> entities = new HashSet<>();
        int rows = 0;
        for (String l : lines) {
            if (l.startsWith("#") || l.isEmpty()) {
                continue;
            }
            String[] f = l.split("\t", -1);
            Check.eq(4, f.length, "row shape: " + l);
            entities.add(f[0]);
            EntityRef ref = EntityRef.parse(f[0] + ":" + f[1]);
            Check.yes(ref != null, "parses: " + l);
            String key = StatKeys.key(ref.entry, ref.parts, f[2]);
            python.add(f[3]);
            java.add(key);
            Check.eq(f[3], key, "key for " + f[0] + " " + f[1] + " " + f[2]);
            rows++;
        }
        Check.eq(python, java, "Java key set equals the Python key set");
        // every tree entity type is in the fixture, and nothing else
        Set<String> tree = new TreeSet<>();
        for (TreeEntry e : MetricTree.ENTRIES) {
            tree.add(e.id);
            Check.yes(MetricNames.of(e.id).length > 0, "metrics for " + e.id);
        }
        Check.eq(new TreeSet<>(entities), tree, "entity types in the fixture equal the tree");
        Check.eq(69, tree.size(), "69 entity types");
        // every kept metric of every type was exercised
        Set<String> seen = new HashSet<>();
        for (String l : lines) {
            if (!l.startsWith("#") && !l.isEmpty()) {
                String[] f = l.split("\t", -1);
                seen.add(f[0] + "\t" + f[2]);
            }
        }
        List<String> missing = new ArrayList<>();
        for (TreeEntry e : MetricTree.ENTRIES) {
            for (String m : MetricNames.of(e.id)) {
                if (!seen.contains(e.id + "\t" + m)) {
                    missing.add(e.id + "/" + m);
                }
            }
        }
        Check.eq(new ArrayList<String>(), missing, "every metric has a Python key row");
        // freshness key
        Check.eq("cptvsan|Collector|lastUpdated", StatKeys.LAST_UPDATED, "freshness key");
        System.out.println("KeyParityTest: " + rows + " rows, " + python.size()
                + " distinct keys, Java == Python");
        Check.done("KeyParityTest");
    }

    static void unused() throws IOException {
        // keeps the import honest if the fixture reader changes
    }
}
